function form_start(string $a,array $p=[],bool $upload=false): void {echo '<form method="post"'.($upload?' enctype="multipart/form-data"':'').'>'.post_hidden($a,$p);}
function end_form(string $label='Guardar'): void {echo '<button type="submit">'.h($label).'</button></form>';}
function urlv(string $v,string $c='',string $e=''): string {return 'index.php?'.http_build_query(array_filter(['v'=>$v,'c'=>$c,'e'=>$e],fn($x)=>$x!==''));}
function a(string $v,string $label,string $c='',string $e='',string $class=''): void {echo '<a class="'.h($class).'" href="'.h(urlv($v,$c,$e)).'">'.h($label).'</a>';}
function profile_form(array $e,string $cid,string $eid,string $action='profile',array $g=[]): void {form_start($action,['c'=>$cid,'e'=>$eid]);echo '<div class="fields">';foreach(['name'=>'Razón social','nif'=>'NIF','zone'=>'Localidad','address'=>'Domicilio','sector'=>'Sector','contact'=>'Responsable','emails'=>'Correo(s) profesional(es)','phone'=>'Teléfono'] as $k=>$label)input($k,$label,$e[$k]??'');select_field('kind','Tipo',['Empresa'=>'Empresa privada','Organismo'=>'Organismo público','Asociación'=>'Asociación'],$e['kind']??'Empresa');if($g)select_field('group','Grupo',$g);echo '</div>';end_form();}
function subprofiles(array $e,string $cid,string $eid,bool $edit,string $only=''): void {foreach(['tutors'=>'Tutores de empresa','sites'=>'Centros de trabajo'] as $type=>$label){if($only!==''&&$type!==$only)continue;echo '<section class="card"><h2>'.h($label).'</h2>';foreach($e[$type] as $sid=>$s){echo '<details><summary>'.h($s['name']).'</summary>';if($edit){form_start('subprofile',['c'=>$cid,'e'=>$eid,'type'=>$type,'sid'=>$sid]);foreach(['name'=>'Nombre','email'=>'Correo','phone'=>'Teléfono','detail'=>$type==='sites'?'Dirección y datos del centro':'Cargo y observaciones'] as $k=>$l)input($k,$l,$s[$k]);end_form();}else echo '<p>'.h($s['email'].' · '.$s['phone'].' · '.$s['detail']).'</p>';echo '</details>';}if($edit){echo '<details><summary>+ Añadir</summary>';form_start('subprofile',['c'=>$cid,'e'=>$eid,'type'=>$type]);foreach(['name'=>'Nombre','email'=>'Correo','phone'=>'Teléfono','detail'=>$type==='sites'?'Dirección y datos del centro':'Cargo y observaciones'] as $k=>$l)input($k,$l);end_form('Añadir');echo '</details>';}echo '</section>';}}
function doc_list(array $d,string $cid,string $eid='',bool $edit=false): void {global $role;echo '<div class="scroll"><table><thead><tr><th>Documento</th><th>Tipo</th><th>Fecha</th><th>Acceso</th></tr></thead><tbody>';foreach($d['docs'] as $id=>$doc){if($doc['course']!==$cid||($eid&&$doc['company']!==$eid)||!auth_doc($d,$doc))continue;echo '<tr><td><a href="index.php?v=download&amp;id='.h($id).'">'.h($doc['name']).'</a><small>'.h($doc['company']?collaboration_label($d,$cid,$doc['company']):'General del curso').'</small></td><td>'.h($doc['category']).'</td><td>'.h(substr($doc['at'],0,10)).'</td><td>'.($doc['shared']?'Compartido':'Centro');if($edit&&$role==='admin'&&$doc['company']){form_start('share',['doc'=>$id,'shared'=>$doc['shared']?'no':'yes']);end_form($doc['shared']?'Retirar acceso':'Compartir');}echo '</td></tr>';}echo '</tbody></table></div>';}
function upload_form(string $cid,string $eid,array $options=[]): void {form_start('upload',$options?['c'=>$cid]:['c'=>$cid,'e'=>$eid],true);if($options)select_field('e','Empresa / ámbito',$options);select_field('category','Tipo de documento',array_combine($x=['Convenio','Plan formativo','Anexo','Evaluación','Seguimiento','Certificado','Subvención','Otro'],$x));echo '<label>Archivo (PDF, DOCX, XLSX, ODT, ODS o imagen; máx. 10 MB)<input type="file" name="file" required accept=".pdf,.docx,.xlsx,.odt,.ods,.png,.jpg,.jpeg"></label>';if(($_SESSION['role']??'')==='admin')echo '<label class="check"><input type="checkbox" name="shared" value="yes"> Compartir exclusivamente con la empresa seleccionada</label>';end_form('Subir documento');}
