<?php elseif($view==='company'): $l=participation($d,$cid,$eid);$e=$l['snapshot']??company($d,$eid);?><div class="actions"><?php a('directory','← Directorio',$cid);a('export','Descargar expediente de la empresa',$cid,$eid,'button secondary');?></div><section class="card"><h2><?=h($e['name'])?></h2><?php if($ed){profile_form($e,$cid,$eid);camp_permission_ui($d,$cid,$eid);}else echo '<p>'.h($e['zone'].' · '.$e['emails'].' · '.$e['phone']).'</p>';?></section><div class="two"><?php subprofiles($e,$cid,$eid,$ed);?></div><div class="two"><section class="card"><h2>Seguimiento · <?=h($gs[$l['group']]??$l['group'])?> · <?=h($c['name'])?></h2><?php if($ed){form_start('link',['c'=>$cid,'e'=>$eid]);select_field('status','Estado',array_combine($statuses,$statuses),$l['status']);select_field('group','Grupo',$gs,$l['group']);input('requested','Plazas solicitadas/ofrecidas',$l['requested'],'number');input('confirmed','Plazas confirmadas',$l['confirmed'],'number');input('next','Próximo contacto',$l['next'],'date');area('notes','Observaciones internas',$l['notes']);end_form();}else echo '<p>'.h($l['status'].' · '.$l['confirmed'].' confirmadas').'</p>';?><h3>Comunicaciones</h3><?php $mail=camp_emails($e)[0]??'';if($ed)pc_contact_ui($d,$cfg,$cid,$eid);?><h3>Historial</h3><?php foreach(array_reverse($l['history']) as $hist)echo '<p class="event">'.h(($hist['at']??$hist['date']??'').' · '.($hist['type']??'').' · '.($hist['note']??$hist['notes']??'')).'</p>';if($ed){form_start('history',['c'=>$cid,'e'=>$eid]);select_field('type','Canal',array_combine($x=['Correo','Llamada','Visita','Reunión','Otro'],$x));area('note','Resultado');end_form('Registrar contacto');}?></section><section class="card"><h2>Acceso de empresa</h2><?php if(isset($_SESSION['invite_link'])){echo '<p class="notice">Enlace de un solo uso; compártalo solo con el destinatario autorizado. Caduca en 7 días.</p><textarea readonly rows="4">'.h($_SESSION['invite_link']).'</textarea>';unset($_SESSION['invite_link']);}if($ed){if(valid_public_url($cfg['public_url']??'')||(!empty($cfg['public_url'])&&!($cfg['https_required']??true))){form_start('invite',['c'=>$cid,'e'=>$eid]);input('email','Correo individual autorizado',$mail,'email',true);end_form('Enviar invitación por correo');}else echo '<p>Configure la URL pública en Configuración para generar invitaciones.</p>';}foreach($d['accounts'] as $aid=>$acc)if(($acc['company']??'')===master_id($eid)){echo '<p>'.h($acc['email']).'</p>';form_start('revoke',['c'=>$cid,'e'=>$eid,'account'=>$aid]);end_form('Revocar acceso');}echo '<h3>Documentos del curso</h3>';doc_list($d,$cid,$eid);if($ed)upload_form($cid,$eid);?></section></div>
<?php elseif($view==='agenda'):?><section class="card"><h2>Próximos contactos</h2><div class="scroll"><table><tr><th>Fecha</th><th>Empresa</th><th>Estado</th><th>Observaciones</th></tr><?php $agenda=array_filter($links,fn($l)=>$l['next']!=='');uasort($agenda,fn($a,$b)=>strcmp($a['next'],$b['next']));foreach($agenda as $id=>$l){echo '<tr><td>'.h($l['next']).($l['next']<date('Y-m-d')?' · Vencido':'').'</td><td>';a('company',collaboration_label($d,$cid,(string)$id),$cid,$id);echo '</td><td>'.h($l['status']).'</td><td>'.h($l['notes']).'</td></tr>';}?></table></div></section>
<?php elseif($view==='students'): $companies=[''=>'Sin asignar'];$sites=[''=>'Sin indicar'];$tutors=[''=>'Sin indicar'];foreach($links as $id=>$l){$e=$l['snapshot']??company($d,(string)$id);$companies[$id]=$e['name'].' · '.($gs[$l['group']]??$l['group']).' ('.$l['confirmed'].' plazas)';foreach($e['sites'] as $sid=>$s)$sites[$sid]=$e['name'].' · '.$s['name'];foreach($e['tutors'] as $tid=>$t)$tutors[$tid]=$e['name'].' · '.$t['name'];}function student_form($sid,$s,$cid,$gs,$companies,$sites,$tutors){form_start('student',['c'=>$cid,'sid'=>$sid]);echo '<div class="fields">';input('name','Nombre',$s['name']??'');select_field('group','Grupo',$gs,$s['group']??'');input('zone','Residencia',$s['zone']??'');select_field('company','Empresa',$companies,$s['company']??'');select_field('site','Centro de trabajo de la empresa elegida',$sites,$s['site']??'');select_field('tutor','Tutor de la empresa elegida',$tutors,$s['tutor']??'');echo '</div>';area('notes','Observaciones internas',$s['notes']??'');end_form();} ?><section class="card"><h2>Alumnado del curso</h2><?php foreach($students as $sid=>$s){echo '<details><summary>'.h(($s['name']?:$sid).' · '.($gs[$s['group']]??'').' · '.($companies[$s['company']]??'Sin asignar')).'</summary>';if($ed)student_form($sid,$s,$cid,$gs,$companies,$sites,$tutors);else echo '<p>'.h($s['zone'].' · '.$s['notes']).'</p>';echo '</details>';}if($ed&&$gs){echo '<h3>Añadir alumno</h3>';student_form('',[],$cid,$gs,$companies,$sites,$tutors);}?></section>
<?php elseif($view==='documents'):?><section class="card"><h2>Expediente de <?=h($c['name'])?></h2><p>Descarga todos los documentos, fichas empresariales, seguimiento y alumnado del curso.</p><?php a('export','Descargar expediente ZIP',$cid,'','button');doc_list($d,$cid,'',$ed);if($ed){echo '<h3>Incorporar documentación</h3>';$choices=[''=>'General del curso (solo centro)'];foreach($links as $id=>$l)$choices[$id]=collaboration_label($d,$cid,(string)$id);upload_form($cid,'',$choices);}echo '<h3>Expedientes por empresa</h3>';foreach($links as $id=>$l){echo '<p>';a('export',($l['snapshot']??company($d,(string)$id))['name'].' · ZIP',$cid,$id);echo '</p>';}?><p><a href="https://www.gobiernodecanarias.org/boc/2025/176/3174.html" target="_blank" rel="noopener noreferrer">Modelo oficial de convenio (BOC)</a></p></section>
<?php else: echo '<p>Sección no encontrada.</p>';endif;?></div><?php endif; ?>
</main><?php if($role)echo '</div>';?><footer><div class="bar"><strong>FP Dual Conecta · Administración y Gestión · <?=h($set['center'])?></strong><a href="mailto:<?=h($set['contact'])?>"><?=h($set['contact'])?></a></div></footer></body></html>
